<body>
<div class="game-container">
    <canvas id="billiards" width="800" height="400"></canvas>
    <div class="ui-overlay">
        <div id="instructions">Drag on the white cue ball to aim and shoot! Longer drag = more power.</div>
        <button id="resetBtn">Rack Balls</button>
    </div>
