                    }


                    ctx.beginPath();
                    ctx.arc(x-2 - Math.cos(angleOffset)*RADIUS/4, y+2 + Math.sin(angleOffset)*RADIUS/4, RADIUS*1.3, 0, Math.PI*2);

                    if(ball.cue) {

                        // Add subtle reflection on ball surface for depth with pulsing effect
                        let ir = Math.floor(power * 255), ig = Math.floor((power)*g), ib=0;

                        const rVal = Math.floor(power * 255);
                        const gVal = Math.floor((power) * g); // Use same power factor


                        ballGradient2.addColorStop(0.7, `rgba(${rVal},${gVal},0,${pwrAlpha})`);

                    } else {

                        let ir = Math.floor(power*255), ig = 255 - Math.floor(power*255), ib=0;

                        ballGradient2.addColorStop(0.7, `rgba(${ir},${ig},0,${pwrAlpha})`);

                    }

                    ctx.fillStyle = ballGradient2;
                }

                ctx.fill();


            } else {
                // Regular balls without aim line (just draw them normally)
                let rVal = Math.floor(power*255), gVal = 255 - Math.floor(power*255);

                const ballGradient2_1 = ctx.createRadialGradient(
                    x, y, 3, 
                    x + dx - ball.vx*3, y + dy - ball.vy*3, RADIUS-4
                );

                if(ball.cue) {

                    // Add subtle reflection on ball surface for depth with pulsing effect to regular balls too
                    let ir = Math.floor(power * 255), ig = Math.floor((power)*g);

                    const rVal = Math.floor(power * 255);
                    const gVal = Math.floor((power) * g); // Use same power factor


